#!/usr/bin/env bash
# Applies MyCar's customizations to the Android project generated by `npx cap add android`.
set -euo pipefail

RUN="${GITHUB_RUN_NUMBER:-1}"
VERSION="${APP_VERSION:-1.01}"
APP=android/app
RES=$APP/src/main/res

# 1) Icons, notification icon, splash
find "$RES" -name 'splash.png' -delete
cp -R android-res/. "$RES/"

# 2) Permissions: GPS location (works offline), reminders, network state
MAN=$APP/src/main/AndroidManifest.xml
perl -0pi -e 's|</manifest>|    <uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION" />\n    <uses-permission android:name="android.permission.ACCESS_FINE_LOCATION" />\n    <uses-feature android:name="android.hardware.location.gps" android:required="false" />\n    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />\n    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />\n    <uses-permission android:name="android.permission.SCHEDULE_EXACT_ALARM" />\n    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED" />\n    <uses-permission android:name="android.permission.VIBRATE" />\n</manifest>|' "$MAN"

# 3) Blue splash with the drop on Android 12+
STY=$RES/values/styles.xml
perl -0pi -e 's|(<style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen">)|$1\n        <item name="windowSplashScreenBackground">#1652F0</item>\n        <item name="windowSplashScreenAnimatedIcon">\@mipmap/ic_launcher_foreground</item>|' "$STY"

# 4) Target SDK 34 (classic status bar; the app is installed directly, not from Play)
sed -i -E 's/targetSdkVersion = [0-9]+/targetSdkVersion = 34/' android/variables.gradle

# 5) Version: name is the product version, code is the build number (so every APK installs as an update)
sed -i -E "s/versionCode [0-9]+/versionCode ${RUN}/; s/versionName \"[^\"]*\"/versionName \"${VERSION}\"/" "$APP/build.gradle"

# 6) Release signing with the permanent key (password from GitHub secrets)
cat >> "$APP/build.gradle" <<'GRADLE'

android {
    signingConfigs {
        mycar {
            storeFile file("release.jks")
            storePassword System.getenv("MYCAR_STORE_PASSWORD")
            keyAlias System.getenv("MYCAR_KEY_ALIAS")
            keyPassword System.getenv("MYCAR_KEY_PASSWORD")
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.mycar
            minifyEnabled false
        }
    }
}
GRADLE

echo "--- manifest permissions"; grep -n 'uses-permission\|uses-feature' "$MAN"
echo "--- launch style"; grep -n -A3 'NoActionBarLaunch' "$STY"
echo "--- versions"; grep -n -E 'versionCode|versionName' "$APP/build.gradle"; grep -n targetSdk android/variables.gradle
